install_command:
set -e

# Determine platform
OS="$(uname -s)"
ARCH="$(uname -m)"

case "$OS" in
  Linux)   PLATFORM_OS="linux" ;;
  Darwin)  PLATFORM_OS="darwin" ;;
  *) echo "Unsupported OS: $OS" >&2; exit 1 ;;
esac

case "$ARCH" in
  x86_64|amd64)   PLATFORM_ARCH="amd64" ;;
  arm64|aarch64)  PLATFORM_ARCH="arm64" ;;
  armv7l|armv7)   PLATFORM_ARCH="arm" ;;
  i386|i686)      PLATFORM_ARCH="386" ;;
  *) echo "Unsupported architecture: $ARCH" >&2; exit 1 ;;
esac

FILENAME="yq_${PLATFORM_OS}_${PLATFORM_ARCH}"
URL="https://github.com/mikefarah/yq/releases/latest/download/${FILENAME}"

mkdir -p ./bin
echo "Downloading ${URL} ..."
curl -fsSL "$URL" -o ./bin/yq
chmod +x ./bin/yq

# Quick smoke test (no network needed beyond the download above)
./bin/yq --version >/dev/null 2>&1 || (echo "Downloaded yq failed to run" >&2; exit 1)
